mapper.select:
SELECT sr.* FROM sensor_reading sr
INNER JOIN (
    SELECT zone_id, MAX(read_at) AS max_read
    FROM sensor_reading
    WHERE station_id = #{stationId}
    GROUP BY zone_id
) latest ON (sr.zone_id = latest.zone_id OR (sr.zone_id IS NULL AND latest.zone_id IS NULL))
         AND sr.read_at = latest.max_read
WHERE sr.station_id = #{stationId}
